head.script:
// A standalone SVG has an SVGDocument, while Socket.IO expects HTMLDocument.createElement.
// Supply the HTML element factory before loading the client library.
if (!document.createElement) {
  document.createElement = function (tagName) {
    return document.createElementNS('http://www.w3.org/1999/xhtml', tagName);
  };
}

body.script:
let socket, loggedIn = false, lastMove = 0;
const $ = (id) => document.getElementById(id);
const status = (message, live = false) => { $('status').textContent = message; document.querySelector('.dot').classList.toggle('live', live); };
$('connect').onclick = () => {
  const host = $('host').value.trim().replace(/\/$/, '');
  if (!host) return status('Enter the host address first.');
  if (!window.io) return status('Loading connection library. Try again in a moment.');
  if (socket) socket.disconnect(); status('Connecting…'); socket = io(host, { transports:['websocket'] });
  socket.on('connect', () => socket.emit('login', {password:$('password').value}));
  socket.on('connect_error', () => status('Could not reach that host.'));
  socket.on('login_result', (r) => { if (!r.ok) return status(r.message); loggedIn=true; $('connect-card').hidden=true; $('remote').hidden=false; status(r.message,true); });
  socket.on('monitors', (screens) => { $('monitor').innerHTML=screens.map(s=>`<option value="${s.id}">${s.name} — ${s.width} × ${s.height}</option>`).join(''); });
  socket.on('frame', (frame) => { $('screen').src=`data:image/jpeg;base64,${frame.jpeg}`; });
  socket.on('disconnect', () => { if(loggedIn) status('Disconnected'); loggedIn=false; });
};
$('disconnect').onclick = () => { if(socket) socket.disconnect(); $('remote').hidden=true; $('connect-card').hidden=false; };
$('monitor').onchange = e => socket.emit('select_monitor',{monitor:Number(e.target.value)});
const point = e => { const b=$('screen').getBoundingClientRect(); return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}; };
$('screen').addEventListener('mousemove', e => { if(loggedIn && Date.now()-lastMove>30) { lastMove=Date.now(); socket.emit('pointer',{...point(e),action:'move'}); }});
$('screen').addEventListener('click', e => { if(loggedIn) socket.emit('pointer',{...point(e),action:'click',button:'left'}); });
$('screen').addEventListener('contextmenu', e => { e.preventDefault(); if(loggedIn) socket.emit('pointer',{...point(e),action:'click',button:'right'}); });
$('screen').addEventListener('dblclick', e => { if(loggedIn) socket.emit('pointer',{...point(e),action:'double',button:'left'}); });
$('screen').addEventListener('wheel', e => { if(loggedIn) { e.preventDefault(); socket.emit('scroll',{amount:e.deltaY>0?-3:3}); }}, {passive:false});
window.addEventListener('keydown', e => { if(!loggedIn || document.activeElement.tagName==='INPUT') return; e.preventDefault(); socket.emit('key',{key:e.key,ctrl:e.ctrlKey,alt:e.altKey,shift:e.shiftKey,meta:e.metaKey}); });
